  'Adhan': 'ബാങ്ക്',
  'Adhan alerts and their toggles': 'ബാങ്ക് അറിയിപ്പുകളും അവയുടെ സ്വിച്ചുകളും',
  'Adhan at its time': 'ബാങ്ക് അതിന്റെ സമയത്ത്',
  'Adhan for other prayers': 'മറ്റ് നിസ്കാരങ്ങൾക്കുള്ള ബാങ്ക്',
  'Adhan, a quiet reminder before each prayer, and a verse each morning. Every one of these can be switched off later, and nothing is scheduled until you allow it.': 'ബാങ്ക്, ഓരോ നിസ്കാരത്തിനും മുമ്പ് ഒരു ശാന്തമായ ഓർമ്മപ്പെടുത്തൽ, ഓരോ പ്രഭാതത്തിലും ഒരു ആയത്ത്. ഇവയെല്ലാം പിന്നീട് ഓഫ് ചെയ്യാം, നിങ്ങൾ അനുവദിക്കുന്നതുവരെ ഒന്നും ഷെഡ്യൂൾ ചെയ്യുന്നില്ല.',
  'Adhkar': 'അദ്കാർ',
  'Affirm it sincerely and willingly.': 'അത് നിഷ്കളങ്കമായും മനസ്സോടെയും ഉറപ്പിക്കുക.',
  'After 1 hour': '1 മണിക്കൂറിനുശേഷം',
  'After 1 minute': '1 മിനിറ്റിനുശേഷം',
  'After 15 minutes': '15 മിനിറ്റിനുശേഷം',
  'After 5 minutes': '5 മിനിറ്റിനുശേഷം',
  'After 8 hours': '8 മണിക്കൂറിനുശേഷം',
  'After Isha': 'ഇശായ്ക്കുശേഷം',
  'After every prayer': 'ഓരോ നിസ്കാരത്തിനും ശേഷം',
  'After prayer': 'നിസ്കാരത്തിനുശേഷം',
  'After salah': 'നിസ്കാരത്തിനുശേഷം',
  'After the first takbir, recite Al-Fatihah.': 'ആദ്യത്തെ തക്ബീറിനുശേഷം അൽഫാതിഹ ഓതുക.',
  'After the fourth, pause briefly and conclude with salam.': 'നാലാമത്തേതിനുശേഷം അല്പം നിന്ന് സലാം വച്ച് അവസാനിപ്പിക്കുക.',
  'After the prayer': 'നിസ്കാരത്തിനുശേഷം',
  'After the salam': 'സലാമിനുശേഷം',
  'After the second, send blessings upon the Prophet ﷺ.': 'രണ്ടാമത്തേതിനുശേഷം നബി ﷺ യുടെമേൽ സ്വലാത്ത് ചൊല്ലുക.',
  'After the third, supplicate sincerely for the deceased.': 'മൂന്നാമത്തേതിനുശേഷം മരണപ്പെട്ടയാൾക്കുവേണ്ടി നിഷ്കളങ്കമായി ദുആ ചെയ്യുക.',
  'Ahmed ibn Ali al-Ajamy': 'അഹ്മദ് ഇബ്നു അലി അൽഅജമി',
  'Al-Masjid al-Haram, around the clock': 'അൽമസ്ജിദുൽ ഹറാം, രാപ്പകൽ',
