  'Allow the app to run in the background': 'ആപ്പ് പശ്ചാത്തലത്തിൽ പ്രവർത്തിക്കാൻ അനുവദിക്കുക',
  'Allowed. Every reminder can be switched off in Settings.': 'അനുവദിച്ചു. ഓരോ ഓർമ്മപ്പെടുത്തലും ക്രമീകരണങ്ങളിൽ ഓഫ് ചെയ്യാം.',
