  'Amiri Quran': 'അമീരി ഖുർആൻ',
  'Amount of': 'തുക',
  'An encrypted copy of everything': 'എല്ലാത്തിന്റെയും എൻക്രിപ്റ്റ് ചെയ്ത പകർപ്പ്',
  'An encrypted copy, sealed with a password you choose': 'നിങ്ങൾ തിരഞ്ഞെടുക്കുന്ന ഒരു രഹസ്യവാക്കിനാൽ മുദ്രവച്ച എൻക്രിപ്റ്റ് ചെയ്ത പകർപ്പ്',
  'An estimate, not a certainty': 'ഒരു ഏകദേശ കണക്ക്, ഉറപ്പല്ല',
  'An obligatory prolongation, commonly four to five counts.': 'സാധാരണയായി നാലു മുതൽ അഞ്ചു ഹറക്കത്ത് വരെയുള്ള നിർബന്ധമായ ദീർഘീകരണം.',
  'An open Naskh with generous, clear diacritics': 'ഉദാരവും വ്യക്തവുമായ ചിഹ്നങ്ങളോടുകൂടിയ തുറന്ന നസ്ഖ്',
  'And what could make thee conceive what it is, that Night of Destiny?': 'ഖദ്റിന്റെ രാവ് എന്താണെന്ന് നിങ്ങളെ അറിയിച്ചതെന്ത്?',
  'Android is not allowing this app to set exact alarms, so the adhan cannot be timed to the prayer. Your notification tone will sound instead. Allow alarms and it will play properly.': 'ഈ ആപ്പിനെ കൃത്യമായ അലാറങ്ങൾ സജ്ജമാക്കാൻ ആൻഡ്രോയ്ഡ് അനുവദിക്കുന്നില്ല, അതിനാൽ ബാങ്ക് നിസ്കാര സമയത്തിനനുസരിച്ച് മുഴക്കാനാവില്ല. പകരം നിങ്ങളുടെ അറിയിപ്പ് ശബ്ദം മുഴങ്ങും. അലാറങ്ങൾ അനുവദിച്ചാൽ അത് ശരിയായി പ്ലേ ചെയ്യും.',
  'Android sometimes delays alarms for apps it thinks are idle, which can make the adhan arrive late. Exempting this app takes one tap.': 'നിഷ്ക്രിയമെന്ന് കരുതുന്ന ആപ്പുകളുടെ അലാറങ്ങൾ ആൻഡ്രോയ്ഡ് ചിലപ്പോൾ വൈകിപ്പിക്കുന്നു, അതിനാൽ ബാങ്ക് വൈകിയെത്താം. ഈ ആപ്പിനെ ഒഴിവാക്കാൻ ഒരു ടാപ്പ് മതി.',
  'Android will not delay this app’s reminders while it is saving power.': 'വൈദ്യുതി ലാഭിക്കുമ്പോഴും ആൻഡ്രോയ്ഡ് ഈ ആപ്പിന്റെ ഓർമ്മപ്പെടുത്തലുകൾ വൈകിപ്പിക്കില്ല.',
  'Another sets no minimum at all, and counts any bleeding as hayd once it has begun.': 'മറ്റൊന്ന് ഒരു കുറഞ്ഞ പരിധിയും വയ്ക്കുന്നില്ല, തുടങ്ങിക്കഴിഞ്ഞാൽ ഏത് രക്തസ്രാവവും ഹൈദായി കണക്കാക്കുന്നു.',
  'Anxiety and distress': 'ഉത്കണ്ഠയും വിഷമവും',
  'Any fast already missed in the hayd portion is still owed, and belongs on the Qada screen.': 'ഹൈദിന്റെ ഭാഗത്ത് ഇതിനകം വിട്ടുപോയ ഏത് നോമ്പും ഇനിയും ബാക്കിയുണ്ട്, അത് ഖദാ സ്ക്രീനിലാണ് ഉൾപ്പെടുന്നത്.',
  'Any other reason': 'മറ്റേതെങ്കിലും കാരണം',
  'Any time': 'ഏത് സമയവും',
  'Anything perfumed — scented product in ihram breaks a restriction': 'സുഗന്ധമുള്ള എന്തും — ഇഹ്റാമിൽ സുഗന്ധ ഉൽപ്പന്നം ഒരു നിബന്ധന ലംഘിക്കുന്നു',
