  'Assimilation accompanied by nasal resonance.': 'മൂക്കിലെ മൂളലോടെയുള്ള ചേർക്കൽ.',
  'Assimilation of mīm sākin into a following mīm.': 'സാകിനായ മീം പിന്നാലെ വരുന്ന മീമിൽ ചേരുന്നു.',
  'Assimilation without nasal resonance.': 'മൂക്കിലെ മൂളൽ ഇല്ലാതെയുള്ള ചേർക്കൽ.',
  'Astaghfirullah': 'അസ്തഗ്ഫിറുല്ലാഹ്',
  'At Mina, stone the large pillar (al-‘Aqabah, the one nearest Makkah) with seven pebbles, saying “Allāhu akbar” with each throw. With this stoning the greater release from Ihram takes effect.': 'മിനായിൽ, വലിയ ജംറയിൽ (അൽഅഖബ, മക്കയോട് ഏറ്റവും അടുത്തത്) ഏഴു കല്ലുകൾ എറിയുക, ഓരോ എറിയലിലും «അല്ലാഹു അക്ബർ» എന്ന് പറയുക. ഈ കല്ലെറിയലോടെ ഇഹ്റാമിൽ നിന്നുള്ള വലിയ മോചനം നടപ്പിലാകുന്നു.',
  'At each prayer time, with buttons to silence it or to mark the prayer as prayed.': 'ഓരോ നിസ്കാര സമയത്തും, അത് നിശ്ശബ്ദമാക്കാനോ നിസ്കാരം നിർവഹിച്ചതായി അടയാളപ്പെടുത്താനോ ഉള്ള ബട്ടണുകളോടെ.',
  'At least 8 characters': 'ചുരുങ്ങിയത് 8 അക്ഷരങ്ങൾ',
