  'Begin the day with authentic remembrance': 'ദിവസം ആരംഭിക്കുക സ്ഥിരീകരിച്ച ദിക്‌റോടെ',
  'Begin with Bismillah and the intention to lift the major impurity.': 'ബിസ്മി ചൊല്ലിയും വലിയ അശുദ്ധി നീക്കാനുള്ള നിയ്യത്തോടെയും ആരംഭിക്കുക.',
  'Begin with intention and say Bismillah.': 'നിയ്യത്തോടെ ആരംഭിച്ച് ബിസ്മി ചൊല്ലുക.',
