  'Bismillah': 'ബിസ്മി',
  'Bleeding after childbirth is commonly counted up to 40 days.': 'പ്രസവത്തിനുശേഷമുള്ള രക്തസ്രാവം സാധാരണയായി 40 ദിവസം വരെ കണക്കാക്കുന്നു.',
  'Bleeding after childbirth is commonly counted up to {n} days.': 'പ്രസവത്തിനുശേഷമുള്ള രക്തസ്രാവം സാധാരണയായി {n} ദിവസം വരെ കണക്കാക്കുന്നു.',
  'Bleeding after childbirth is counted as nifas while it lasts, up to the outer limit. Its rules follow those of hayd for the days it runs.': 'പ്രസവത്തിനുശേഷമുള്ള രക്തസ്രാവം അത് നീണ്ടുനിൽക്കുന്നിടത്തോളം, അതായത് അതിരുവരെ, നിഫാസായി കണക്കാക്കുന്നു. അത് നടക്കുന്ന ദിവസങ്ങളിൽ അതിന്റെ നിയമങ്ങൾ ഹൈദിന്റേതിനെ പിന്തുടരുന്നു.',
  'Bleeding days': 'രക്തസ്രാവ ദിവസങ്ങൾ',
  'Bleeding is not always hayd, and the difference decides whether the prayer and the fast are due. Answer the two questions below and the app will hold them against your own pattern and against the limits commonly cited.': 'രക്തസ്രാവം എല്ലായ്പ്പോഴും ഹൈദല്ല, ആ വ്യത്യാസമാണ് നിസ്കാരവും നോമ്പും നിർബന്ധമാണോ എന്ന് തീരുമാനിക്കുന്നത്. താഴെയുള്ള രണ്ടു ചോദ്യങ്ങൾക്ക് ഉത്തരം നൽകുക, നിങ്ങളുടെ സ്വന്തം ക്രമത്തോടും സാധാരണ ഉദ്ധരിക്കപ്പെടുന്ന പരിധികളോടും ആപ്പ് അവയെ താരതമ്യം ചെയ്യും.',
  'Bleeding outside the pattern of hayd or nifas: ongoing spotting, a wound, or bleeding that runs past the limits above. It does not prevent the prayer or the fast. The well-known guidance is to wash, protect the area, and make wudu for the time of each prayer rather than once for the day.': 'ഹൈദിന്റെയോ നിഫാസിന്റെയോ ക്രമത്തിനു പുറത്തുള്ള രക്തസ്രാവം: തുടർച്ചയായ നേരിയ രക്തം, ഒരു മുറിവ്, അല്ലെങ്കിൽ മുകളിലെ പരിധികൾക്കപ്പുറം നീളുന്ന രക്തസ്രാവം. ഇത് നിസ്കാരത്തെയോ നോമ്പിനെയോ തടയുന്നില്ല. അറിയപ്പെടുന്ന മാർഗ്ഗദർശനം: കഴുകുക, ഭാഗം സംരക്ഷിക്കുക, ഒരു ദിവസത്തിന് ഒരിക്കലല്ല, ഓരോ നിസ്കാര സമയത്തിനും വുദു ചെയ്യുക.',
  'Bleeding that begins inside that gap is not counted as a new period.': 'ആ ഇടവേളയ്ക്കുള്ളിൽ തുടങ്ങുന്ന രക്തസ്രാവം ഒരു പുതിയ ആർത്തവമായി കണക്കാക്കുന്നില്ല.',
  'Bleeding that continues past the outer limit is treated as istihada from that point.': 'അതിരിനപ്പുറം തുടരുന്ന രക്തസ്രാവം അവിടം മുതൽ ഇസ്തിഹാദയായി കണക്കാക്കുന്നു.',
