  'Choosing a language here changes the meaning shown for every Name. It does not change the Quran translation you picked elsewhere': 'ഇവിടെ ഒരു ഭാഷ തിരഞ്ഞെടുക്കുന്നത് ഓരോ നാമത്തിനും കാണിച്ചിരിക്കുന്ന അർത്ഥം മാറ്റുന്നു. നിങ്ങൾ മറ്റെവിടെയെങ്കിലും തിരഞ്ഞെടുത്ത ഖുർആൻ വിവർത്തനം അത് മാറ്റുന്നില്ല',
