  'Commonly observed, and disputed. The reports about it are not all sound.': 'സാധാരണയായി അനുഷ്ഠിക്കപ്പെടുന്നു, എന്നാൽ തർക്കവിഷയമാണ്. അതിനെക്കുറിച്ചുള്ള റിപ്പോർട്ടുകളെല്ലാം സ്വഹീഹല്ല.',
