  'Compiled': 'സമാഹരിച്ചത്',
  'Complete Surah recitations from published reciters, used when you play a whole Surah rather than verse by verse.': 'പ്രസിദ്ധീകരിച്ച ഖാരിമാരിൽ നിന്നുള്ള പൂർണ്ണ സൂറത്ത് ഓതലുകൾ, ആയത്ത് ആയത്തായല്ല, മുഴുവൻ സൂറത്ത് പ്ലേ ചെയ്യുമ്പോൾ ഉപയോഗിക്കുന്നു.',
  'Complete Surah recordings — one continuous track per Surah.': 'പൂർണ്ണ സൂറത്ത് റെക്കോർഡിംഗുകൾ — ഓരോ സൂറത്തിനും ഒരു തുടർച്ചയായ ട്രാക്ക്.',
  'Complete dryness: nothing at all is seen when checking, so the place remains clean and dry. For many women this is the clearer of the two signs, and it is reached a day or two after the discharge stops.': 'പൂർണ്ണ വരൾച്ച: പരിശോധിക്കുമ്പോൾ ഒന്നും കാണുന്നില്ല, അതിനാൽ ഭാഗം വൃത്തിയായും വരണ്ടുമിരിക്കുന്നു. പല സ്ത്രീകൾക്കും ഇതാണ് രണ്ടു ലക്ഷണങ്ങളിൽ കൂടുതൽ വ്യക്തമായത്, സ്രവം നിൽക്കുന്നതിന് ഒന്നോ രണ്ടോ ദിവസം കഴിഞ്ഞ് ഇതിലെത്തുന്നു.',
  'Complete journey': 'യാത്ര പൂർത്തിയാക്കുക',
  'Complete the Quran': 'ഖുർആൻ പൂർത്തിയാക്കുക',
