  'Complete this journey': 'ഈ യാത്ര പൂർത്തിയാക്കുക',
  'Completed': 'പൂർത്തിയായി',
  'Completed journeys': 'പൂർത്തിയായ യാത്രകൾ',
  'Completed readings': 'പൂർത്തിയായ വായനകൾ',
  'Concise educational overviews with transparent Qur’an and Hadith references. Detailed rulings should be learned from a qualified local scholar.': 'സുതാര്യമായ ഖുർആൻ, ഹദീസ് അവലംബങ്ങളോടുകൂടിയ സംഗ്രഹ വിദ്യാഭ്യാസ അവലോകനങ്ങൾ. വിശദമായ വിധികൾ യോഗ്യതയുള്ള ഒരു പ്രാദേശിക പണ്ഡിതനിൽ നിന്ന് പഠിക്കണം.',
