  'Counted as hayd': 'ഹൈദായി കണക്കാക്കി',
  'Counted as istihada — not a period': 'ഇസ്തിഹാദയായി കണക്കാക്കി — ആർത്തവമല്ല',
  'Counted as post-natal bleeding (nifas)': 'പ്രസവാനന്തര രക്തസ്രാവമായി കണക്കാക്കി (നിഫാസ്)',
  'Counted from your last {n} recorded cycles.': 'നിങ്ങളുടെ അവസാന {n} രേഖപ്പെടുത്തിയ ചക്രങ്ങളിൽ നിന്ന് കണക്കാക്കി.',
  'Counted today': 'ഇന്ന് എണ്ണിയത്',
