  'Cycle Tracker': 'ആർത്തവ ട്രാക്കർ',
  'Cycle and purity records, the days after childbirth, and the fasts owed because of them — kept only on this device. Nothing is uploaded and no account is involved.': 'ചക്രത്തിന്റെയും ശുദ്ധിയുടെയും രേഖകൾ, പ്രസവാനന്തര ദിവസങ്ങൾ, അവ കാരണം ബാക്കിയുള്ള നോമ്പുകൾ — ഈ ഉപകരണത്തിൽ മാത്രം സൂക്ഷിച്ചിരിക്കുന്നു. ഒന്നും അപ്‌ലോഡ് ചെയ്യുന്നില്ല, അക്കൗണ്ടും വേണ്ട.',
