  'Deodorant without perfume; a crystal or alum stick is the safe bet': 'സുഗന്ധമില്ലാത്ത ഡിയോഡറന്റ്; ഒരു ക്രിസ്റ്റൽ അല്ലെങ്കിൽ അലം സ്റ്റിക്കാണ് സുരക്ഷിതം',
  'Details differ between legal schools; follow the imam and seek local scholarly guidance.': 'വിശദാംശങ്ങൾ മദ്‌ഹബുകൾക്കിടയിൽ വ്യത്യാസപ്പെടുന്നു; ഇമാമിനെ പിന്തുടരുകയും പ്രാദേശിക പണ്ഡിത മാർഗ്ഗദർശനം തേടുകയും ചെയ്യുക.',
  'Deutsch': 'ജർമ്മൻ',
  'Dhikr': 'ദിക്‌ർ',
  'Dhikr counter': 'ദിക്‌ർ കൗണ്ടർ',
  'Dhikr, dua, charity, kindness to family, listening to the Quran, and seeking knowledge all continue. Nothing about these days closes the door to a person’s relationship with Allah — they are part of the worship of a woman’s life, not a suspension of it. Many find the regular adhkar of morning and evening especially valuable here, since the habit continues even when the prayer does not.': 'ദിക്‌ർ, ദുആ, സദഖ, കുടുംബത്തോടുള്ള കരുണ, ഖുർആൻ കേൾവി, വിജ്ഞാനം തേടൽ എന്നിവയെല്ലാം തുടരുന്നു. ഈ ദിവസങ്ങൾ ഒരാളുടെ അല്ലാഹുവുമായുള്ള ബന്ധത്തിന് വാതിൽ അടയ്ക്കുന്നില്ല — അവ ഒരു സ്ത്രീയുടെ ജീവിതത്തിലെ ആരാധനയുടെ ഭാഗമാണ്, അതിന്റെ താൽക്കാലിക നിർത്തലല്ല. പ്രഭാതത്തിലെയും സന്ധ്യയിലെയും സ്ഥിരമായ അദ്കാർ ഇവിടെ പ്രത്യേകിച്ച് മൂല്യവത്തായി പലരും കാണുന്നു, കാരണം നിസ്കാരമില്ലെങ്കിലും ആ ശീലം തുടരുന്നു.',
  'Dhikr, tasbih and istighfar': 'ദിക്‌ർ, തസ്ബീഹ്, ഇസ്തിഗ്ഫാർ',
