  'List what you own, subtract what falls due, and compare what is left with the nisab. Prices and exchange rates are fetched live where they are reachable and kept on this device when they are not. This is arithmetic, not a ruling — take the details to a scholar.': 'നിങ്ങളുടെ കൈവശമുള്ളത് പട്ടികപ്പെടുത്തുക, നിർബന്ധമായത് കുറയ്ക്കുക, ബാക്കിയുള്ളത് നിസാബുമായി താരതമ്യം ചെയ്യുക. വിലകളും വിനിമയ നിരക്കുകളും ലഭിക്കുന്നിടത്ത് തത്സമയം എടുക്കുന്നു, ലഭിക്കാത്തപ്പോൾ ഈ ഉപകരണത്തിൽ സൂക്ഷിക്കുന്നു. ഇതൊരു കണക്കാണ്, വിധിയല്ല — വിശദാംശങ്ങൾ ഒരു പണ്ഡിതന്റെ അടുത്ത് കൊണ്ടുപോകുക.',
