  'Mark one above and this day will appear here.': 'മുകളിൽ ഒന്ന് അടയാളപ്പെടുത്തുക, ഈ ദിവസം ഇവിടെ കാണാം.',
  'Mark pages read': 'വായിച്ച പേജുകൾ അടയാളപ്പെടുത്തുക',
  'Mark position at': 'സ്ഥാനം അടയാളപ്പെടുത്തുക',
  'Mark purity today': 'ഇന്ന് ശുദ്ധി അടയാളപ്പെടുത്തുക',
  'Mark read': 'വായിച്ചതായി അടയാളപ്പെടുത്തുക',
  'Mark this remembrance as read': 'ഈ ദിക്‌ർ വായിച്ചതായി അടയാളപ്പെടുത്തുക',
  'Mark verses cut across a page': 'പേജ് കടന്നുപോകുന്ന ആയത്തുകൾ അടയാളപ്പെടുത്തുക',
  'Marked as known': 'അറിയാമെന്ന് അടയാളപ്പെടുത്തി',
  'Marked for review': 'പുനരവലോകനത്തിനായി അടയാളപ്പെടുത്തി',
  'Market value today': 'ഇന്നത്തെ വിപണി മൂല്യം',
  'May this app remind you?': 'ഈ ആപ്പ് നിങ്ങളെ ഓർമ്മപ്പെടുത്തട്ടെ?',
  'Meaning language': 'അർത്ഥത്തിന്റെ ഭാഷ',
  'Measured as it sits on the device, not as it arrived. Text is compressed on the way in and not once stored, so a translation that downloads as 3 MB takes 11 MB here.': 'എത്തിയതുപോലെയല്ല, ഉപകരണത്തിൽ ഇരിക്കുന്നതുപോലെയാണ് അളക്കുന്നത്. വാചകം വരുമ്പോൾ കംപ്രസ് ചെയ്യുന്നു, സൂക്ഷിക്കുമ്പോൾ അല്ല, അതിനാൽ 3 MB ഡൗൺലോഡാകുന്ന ഒരു വിവർത്തനം ഇവിടെ 11 MB എടുക്കുന്നു.',
  'Memorisation': 'മനഃപാഠം',
  'Mercy, الصبر, or 2:255': 'കാരുണ്യം, الصبر, അല്ലെങ്കിൽ 2:255',
  'More': 'കൂടുതൽ',
  'More actions for verse': 'ആയത്തിനുള്ള കൂടുതൽ പ്രവർത്തനങ്ങൾ',
  'Morning': 'പ്രഭാതം',
  'Morning remembrance': 'പ്രഭാത ദിക്‌ർ',
  'Move to weak bank': 'ദുർബല ശേഖരത്തിലേക്ക് മാറ്റുക',
  'Moving to the weak bank keeps the attempt and holds the verse there. Undoing stops it counting at all.': 'ദുർബല ശേഖരത്തിലേക്ക് മാറ്റുന്നത് ശ്രമം നിലനിർത്തുകയും ആയത്ത് അവിടെ നിർത്തുകയും ചെയ്യുന്നു. പിൻവലിച്ചാൽ അത് ഒട്ടും കണക്കാക്കില്ല.',
  'Mushaf page lays the Quran out as printed pages, fifteen lines to a page, with no translation or verse numbers. Choose it here and the reader becomes a mushaf.': 'മുസ്ഹഫ് പേജ് ഖുർആനിനെ അച്ചടിച്ച പേജുകളായി നിരത്തുന്നു, ഒരു പേജിൽ പതിനഞ്ചു വരികൾ, വിവർത്തനമോ ആയത്ത് നമ്പറുകളോ ഇല്ല. ഇവിടെ അത് തിരഞ്ഞെടുത്താൽ റീഡർ ഒരു മുസ്ഹഫാകുന്നു.',
  'Mushaf page number': 'മുസ്ഹഫ് പേജ് നമ്പർ',
  'Mushaf page {n}': 'മുസ്ഹഫ് പേജ് {n}',
