  'NISAB': 'നിസാബ്',
  'NO CYCLE IN PROGRESS': 'നടന്നുകൊണ്ടിരിക്കുന്ന ചക്രമില്ല',
  'NOT RECORDED YET': 'ഇതുവരെ രേഖപ്പെടുത്തിയിട്ടില്ല',
