  'Next Surah': 'അടുത്ത സൂറത്ത്',
  'Next cycle expected in {n} days': 'അടുത്ത ചക്രം {n} ദിവസത്തിനുള്ളിൽ പ്രതീക്ഷിക്കുന്നു',
