  'Nothing yet': 'ഇതുവരെ ഒന്നുമില്ല',
  'Notifications': 'അറിയിപ്പുകൾ',
  'Now playing': 'ഇപ്പോൾ പ്ലേ ചെയ്യുന്നു',
  'OF': 'ന്റെ',
  'ON THE PAGE': 'പേജിൽ',
