  'OUTSTANDING': 'ബാക്കിയുള്ളത്',
  'Of the five': 'അഞ്ചിൽ',
  'Off': 'ഓഫ്',
  'Offline': 'ഓഫ്‌ലൈൻ',
  'Offline Quran': 'ഓഫ്‌ലൈൻ ഖുർആൻ',
  'Offline · ': 'ഓഫ്‌ലൈൻ · ',
  'On': 'ഓൺ',
  'On the streak': 'തുടർച്ചയിൽ',
  'Once a day is actually missed, keep it here.': 'ഒരു ദിവസം യഥാർത്ഥത്തിൽ വിട്ടുപോയാൽ, അത് ഇവിടെ സൂക്ഷിക്കുക.',
  'One a day is enough for most people. The pace only sets the estimate above — nothing is scheduled for you.': 'മിക്ക ആളുകൾക്കും ഒരു ദിവസം ഒന്ന് മതി. ഈ വേഗം മുകളിലെ ഏകദേശ കണക്ക് മാത്രം നിശ്ചയിക്കുന്നു — നിങ്ങൾക്കായി ഒന്നും ഷെഡ്യൂൾ ചെയ്യുന്നില്ല.',
  'One day earlier': 'ഒരു ദിവസം നേരത്തെ',
  'One day later': 'ഒരു ദിവസം പിന്നീട്',
  'One fewer': 'ഒന്നു കുറയ്ക്കുക',
  'One fewer day owed': 'ബാക്കിയുള്ളത് ഒരു ദിവസം കുറയ്ക്കുക',
  'One hadith each morning, at the hour you choose.': 'ഓരോ പ്രഭാതത്തിലും ഒരു ഹദീസ്, നിങ്ങൾ തിരഞ്ഞെടുക്കുന്ന സമയത്ത്.',
  'One more': 'ഒന്നു കൂട്ടുക',
  'One more day owed': 'ബാക്കിയുള്ളത് ഒരു ദിവസം കൂട്ടുക',
  'One reminder in the morning, and a nudge back to where you were reading.': 'പ്രഭാതത്തിൽ ഒരു ഓർമ്മപ്പെടുത്തൽ, നിങ്ങൾ വായിച്ചിരുന്നിടത്തേക്ക് ഒരു തള്ളൽ.',
  'One verse each morning, at the hour you choose.': 'ഓരോ പ്രഭാതത്തിലും ഒരു ആയത്ത്, നിങ്ങൾ തിരഞ്ഞെടുക്കുന്ന സമയത്ത്.',
  'Only changes what new entries are recorded in — past gifts keep the currency they were given in.': 'പുതിയ എൻട്രികൾ ഏതിലാണ് രേഖപ്പെടുത്തുന്നതെന്ന് മാത്രം മാറ്റുന്നു — കഴിഞ്ഞ ദാനങ്ങൾ അവ നൽകിയ കറൻസിയിൽത്തന്നെ നിലനിൽക്കും.',
  'Only languages that are published are listed. Others are not shown rather than faked.': 'പ്രസിദ്ധീകരിച്ച ഭാഷകൾ മാത്രം പട്ടികപ്പെടുത്തുന്നു. മറ്റുള്ളവ കാണിക്കുന്നില്ല, കെട്ടിച്ചമയ്ക്കുന്നുമില്ല.',
