  'Password': 'രഹസ്യവാക്ക്',
  'Password changed. Backups already made still open with the old one.': 'രഹസ്യവാക്ക് മാറ്റി. നേരത്തെ ഉണ്ടാക്കിയ ബാക്കപ്പുകൾ പഴയതുകൊണ്ടുതന്നെ തുറക്കും.',
  'Password removed. Backups already made still open with it.': 'രഹസ്യവാക്ക് നീക്കം ചെയ്തു. നേരത്തെ ഉണ്ടാക്കിയ ബാക്കപ്പുകൾ അതുകൊണ്ടുതന്നെ തുറക്കും.',
  'Password set. Nothing can recover it — not this app, and not anyone else.': 'രഹസ്യവാക്ക് സജ്ജമാക്കി. അത് വീണ്ടെടുക്കാൻ ഒന്നിനുമാവില്ല — ഈ ആപ്പിനും, മറ്റാർക്കും.',
  'Past forty days — speak to a scholar and a doctor': 'നാല്പതു ദിവസം കഴിഞ്ഞു — ഒരു പണ്ഡിതനോടും ഒരു ഡോക്ടറോടും സംസാരിക്കുക',
  'Paste the whole backup file here': 'മുഴുവൻ ബാക്കപ്പ് ഫയലും ഇവിടെ ഒട്ടിക്കുക',
  'Pause': 'താൽക്കാലികമായി നിർത്തുക',
  'Pause Adhan preview': 'ബാങ്ക് പ്രിവ്യൂ താൽക്കാലികമായി നിർത്തുക',
  'Pause the stream': 'സ്ട്രീം താൽക്കാലികമായി നിർത്തുക',
  'Permission': 'അനുമതി',
  'Permission and scheduling happen on your device. No notification profile is sent to us.': 'അനുമതിയും ഷെഡ്യൂളിംഗും നിങ്ങളുടെ ഉപകരണത്തിൽ നടക്കുന്നു. ഞങ്ങൾക്ക് ഒരു അറിയിപ്പ് പ്രൊഫൈലും അയയ്ക്കുന്നില്ല.',
  'Permission was declined earlier, so reminders stay off. You can turn them on in the system settings for this app at any time.': 'അനുമതി നേരത്തെ നിരസിച്ചു, അതിനാൽ ഓർമ്മപ്പെടുത്തലുകൾ ഓഫായി തുടരുന്നു. എപ്പോൾ വേണമെങ്കിലും ഈ ആപ്പിന്റെ സിസ്റ്റം ക്രമീകരണങ്ങളിൽ അവ ഓണാക്കാം.',
  'Pick up where I left off': 'ഞാൻ നിർത്തിയിടത്തു നിന്ന് തുടരുക',
