  'Prayer times': 'നിസ്കാര സമയങ്ങൾ',
  'Prayer times, Qibla and fasting times read from one place. Tap to choose a city or enter coordinates.': 'നിസ്കാര സമയങ്ങൾ, ഖിബ്‌ല, നോമ്പ് സമയങ്ങൾ എന്നിവ ഒരിടത്തുനിന്നാണ് വായിക്കുന്നത്. ഒരു നഗരം തിരഞ്ഞെടുക്കാനോ നിർദ്ദേശാങ്കങ്ങൾ നൽകാനോ ടാപ്പ് ചെയ്യുക.',
  'Prayer times, Qibla and the fasting timetable all read from one place. Search for your city, or use your location once. This is asked only here — you can change it any time in Settings.': 'നിസ്കാര സമയങ്ങൾ, ഖിബ്‌ല, നോമ്പ് സമയക്രമം എന്നിവയെല്ലാം ഒരിടത്തുനിന്ന് വായിക്കുന്നു. നിങ്ങളുടെ നഗരം തിരയുക, അല്ലെങ്കിൽ ഒരിക്കൽ നിങ്ങളുടെ സ്ഥാനം ഉപയോഗിക്കുക. ഇത് ഇവിടെ മാത്രമേ ചോദിക്കൂ — എപ്പോൾ വേണമെങ്കിലും ക്രമീകരണങ്ങളിൽ മാറ്റാം.',
  'Prayer times, Qibla, Ramadan and nearby mosques all read from this one place. It is asked once and kept on this device.': 'നിസ്കാര സമയങ്ങൾ, ഖിബ്‌ല, റമദാൻ, സമീപത്തെ പള്ളികൾ എന്നിവയെല്ലാം ഈ ഒരിടത്തുനിന്ന് വായിക്കുന്നു. ഇത് ഒരിക്കൽ ചോദിക്കുകയും ഈ ഉപകരണത്തിൽ സൂക്ഷിക്കുകയും ചെയ്യുന്നു.',
