  'Record a birth today': 'ഇന്ന് ഒരു പ്രസവം രേഖപ്പെടുത്തുക',
  'Record a cycle to see your averages': 'നിങ്ങളുടെ ശരാശരി കാണാൻ ഒരു ചക്രം രേഖപ്പെടുത്തുക',
