  'Record a start and an end for each cycle.': 'ഓരോ ചക്രത്തിനും ഒരു തുടക്കവും ഒരു അവസാനവും രേഖപ്പെടുത്തുക.',
  'Record as not fasted': 'നോമ്പെടുത്തില്ലെന്ന് രേഖപ്പെടുത്തുക',
  'Record the birth when it happens and the counter follows the days. Purity is marked the day the bleeding stops.': 'പ്രസവം നടക്കുമ്പോൾ അത് രേഖപ്പെടുത്തുക, കൗണ്ടർ ദിവസങ്ങളെ പിന്തുടരുന്നു. രക്തസ്രാവം നിൽക്കുന്ന ദിവസം ശുദ്ധി അടയാളപ്പെടുത്തുന്നു.',
  'Record the days as they come. The averages and the prediction are worked out from your own history — nothing is assumed about what your cycle should look like.': 'ദിവസങ്ങൾ വരുന്നതനുസരിച്ച് രേഖപ്പെടുത്തുക. ശരാശരികളും പ്രവചനവും നിങ്ങളുടെ സ്വന്തം ചരിത്രത്തിൽ നിന്ന് കണക്കാക്കുന്നു — നിങ്ങളുടെ ചക്രം എങ്ങനെയായിരിക്കണമെന്ന് ഒന്നും അനുമാനിക്കുന്നില്ല.',
  'Record these days so your own pattern stays accurate.': 'നിങ്ങളുടെ സ്വന്തം ക്രമം കൃത്യമായി നിലനിൽക്കാൻ ഈ ദിവസങ്ങൾ രേഖപ്പെടുത്തുക.',
  'Record today as a Ramadan fast': 'ഇന്ന് റമദാൻ നോമ്പായി രേഖപ്പെടുത്തുക',
