  'Remembered': 'ഓർമ്മയിലുള്ളത്',
  'Remembrance for 132 occasions, in Arabic with transliteration and meaning. Each entry keeps the reference the source gives for it.': '132 അവസരങ്ങൾക്കുള്ള ദിക്‌ർ, അറബിയിൽ ലിപ്യന്തരണത്തോടും അർത്ഥത്തോടും കൂടെ. ഓരോ എൻട്രിയും സ്രോതസ്സ് നൽകുന്ന അവലംബം നിലനിർത്തുന്നു.',
  'Remembrance, trusted learning and step-by-step guidance—organized by purpose rather than hidden in a feature grid.': 'ദിക്‌ർ, വിശ്വസനീയമായ പഠനം, ഘട്ടംഘട്ടമായ മാർഗ്ഗദർശനം — ഒരു ഫീച്ചർ ഗ്രിഡിൽ ഒളിപ്പിക്കുന്നതിനു പകരം ലക്ഷ്യമനുസരിച്ച് ക്രമീകരിച്ചിരിക്കുന്നു.',
