  'Salah Tracker': 'നിസ്കാര ട്രാക്കർ',
  'Salah counts the prayers you mark on the Prayer screen. Reading counts the verses you mark in the reader and the Mushaf pages you open. Dhikr comes from the Tasbih counter, and hifz from every verse you rate in recall practice. Thirty days are kept, on this device only, and nothing is uploaded.': 'നിസ്കാരം എന്നത് നിങ്ങൾ നിസ്കാര സ്ക്രീനിൽ അടയാളപ്പെടുത്തുന്ന നിസ്കാരങ്ങളെ എണ്ണുന്നു. വായന എന്നത് റീഡറിൽ നിങ്ങൾ അടയാളപ്പെടുത്തുന്ന ആയത്തുകളും തുറക്കുന്ന മുസ്ഹഫ് പേജുകളും. ദിക്‌ർ തസ്ബീഹ് കൗണ്ടറിൽ നിന്നും, ഹിഫ്ദ് ഓർമ്മ പരിശീലനത്തിൽ നിങ്ങൾ റേറ്റ് ചെയ്യുന്ന ഓരോ ആയത്തിൽ നിന്നും. മുപ്പതു ദിവസം ഈ ഉപകരണത്തിൽ മാത്രം സൂക്ഷിക്കുന്നു, ഒന്നും അപ്‌ലോഡ് ചെയ്യുന്നില്ല.',
