  'Scholars differ on which of the two to measure against. The lower threshold brings more wealth into Zakat; take the choice to someone you trust.': 'ഏതിനോടാണ് അളക്കേണ്ടതെന്നതിൽ പണ്ഡിതന്മാർ വ്യത്യാസപ്പെട്ടിരിക്കുന്നു. താഴ്ന്ന പരിധി സകാത്തിലേക്ക് കൂടുതൽ സമ്പത്ത് കൊണ്ടുവരുന്നു; ഈ തിരഞ്ഞെടുപ്പ് നിങ്ങൾ വിശ്വസിക്കുന്ന ഒരാളുടെ അടുത്ത് കൊണ്ടുപോകുക.',
