  'Surah Al-Mulk takes about five minutes. Say the hour you turn in and we will remind you before it — or skip this entirely. The hour stays on your device and is never used for tracking.': 'സൂറത്തുൽ മുൽക്കിന് ഏകദേശം അഞ്ചു മിനിറ്റ് എടുക്കും. നിങ്ങൾ ഉറങ്ങാൻ കിടക്കുന്ന സമയം പറയുക, അതിനു മുമ്പ് ഞങ്ങൾ നിങ്ങളെ ഓർമ്മപ്പെടുത്തും — അല്ലെങ്കിൽ ഇത് പൂർണ്ണമായും ഒഴിവാക്കുക. ആ സമയം നിങ്ങളുടെ ഉപകരണത്തിൽ നിലനിൽക്കുന്നു, ഒരിക്കലും ട്രാക്കിംഗിന് ഉപയോഗിക്കുന്നില്ല.',
