  'Ten verified collections with matched Arabic and English texts. Grading is shown where the source publishes it—Sahih al-Bukhari and Sahih Muslim carry no separate grade because their contents are accepted as sound.': 'പൊരുത്തപ്പെട്ട അറബി, ഇംഗ്ലീഷ് വാചകങ്ങളുള്ള പത്ത് സ്ഥിരീകരിച്ച ശേഖരങ്ങൾ. സ്രോതസ്സ് പ്രസിദ്ധീകരിക്കുന്നിടത്ത് ഗ്രേഡിംഗ് കാണിച്ചിരിക്കുന്നു — സ്വഹീഹുൽ ബുഖാരിയും സ്വഹീഹു മുസ്‌ലിമും പ്രത്യേക ഗ്രേഡ് നൽകുന്നില്ല, കാരണം അവയുടെ ഉള്ളടക്കം സ്വീകാര്യമായി അംഗീകരിക്കപ്പെട്ടതാണ്.',
