  'Translations explain meaning and do not replace the Arabic Quran. Edition attribution remains visible in the reader.': 'വിവർത്തനങ്ങൾ അർത്ഥം വിശദീകരിക്കുന്നു, അറബി ഖുർആന് പകരമാകുന്നില്ല. പതിപ്പിന്റെ അവലംബം റീഡറിൽ കാണാം.',
  'Transliteration': 'ലിപ്യന്തരണം',
  'Try Dubai, Makkah, London…': 'ദുബൈ, മക്ക, ലണ്ടൻ എന്നിവ പരീക്ഷിക്കുക…',
  'Try again': 'വീണ്ടും ശ്രമിക്കുക',
  'Turn on the women’s area': 'സ്ത്രീകളുടെ ഭാഗം ഓണാക്കുക',
  'Turn on this area': 'ഈ ഭാഗം ഓണാക്കുക',
  'Two cycles needed': 'രണ്ടു ചക്രങ്ങൾ ആവശ്യമാണ്',
  'Two notifications sent — one quiet, one adhan.': 'രണ്ട് അറിയിപ്പുകൾ അയച്ചു — ഒന്ന് ശാന്തം, ഒന്ന് ബാങ്ക്.',
  'Two worships are lifted in these days — the prayer and the fast — and they are lifted as a mercy, not held back as a loss. Nearly everything else you do is untouched by them: the remembrance, the listening, the study, the asking. All of it is still yours, and all of it is already here.': 'ഈ ദിവസങ്ങളിൽ രണ്ട് ആരാധനകൾ ഉയർത്തപ്പെട്ടിരിക്കുന്നു — നിസ്കാരവും നോമ്പും — അവ ഒരു കാരുണ്യമായാണ് ഉയർത്തപ്പെട്ടിരിക്കുന്നത്, നഷ്ടമായി പിടിച്ചുവച്ചിട്ടല്ല. നിങ്ങൾ ചെയ്യുന്ന മറ്റെല്ലാറ്റിലും അവയുടെ സ്പർശമില്ല: ദിക്‌ർ, കേൾവി, പഠനം, ചോദിക്കൽ. എല്ലാം ഇപ്പോഴും നിങ്ങളുടേതാണ്, എല്ലാം ഇവിടെയുണ്ട്.',
