  'Verse-by-verse: one track for each ayah. Full-Surah: a complete recitation of the Surah.': 'ആയത്ത് ആയത്തായി: ഓരോ ആയത്തിനും ഒരു ട്രാക്ക്. പൂർണ്ണ സൂറത്ത്: സൂറത്തിന്റെ സമ്പൂർണ്ണ ഓതൽ.',
  'Verses': 'ആയത്തുകൾ',
  'Verses under this are drawn more often. Anything you flag yourself counts as weak whatever it scores.': 'ഇതിനു താഴെയുള്ള ആയത്തുകൾ കൂടുതൽ തവണ എടുക്കുന്നു. നിങ്ങൾ സ്വയം ഫ്ലാഗ് ചെയ്യുന്നതെന്തും അതിന്റെ സ്കോർ എന്തായാലും ദുർബലമായി കണക്കാക്കും.',
