  '“Finish this reading” files it as complete and begins the next one — for a reading finished before you installed the app.': '«ഈ വായന പൂർത്തിയാക്കുക» അതിനെ പൂർത്തിയായതായി രേഖപ്പെടുത്തുകയും അടുത്തത് ആരംഭിക്കുകയും ചെയ്യുന്നു — നിങ്ങൾ ആപ്പ് ഇൻസ്റ്റാൾ ചെയ്യുന്നതിനു മുമ്പ് പൂർത്തിയാക്കിയ ഒരു വായനയ്ക്ക്.',
  '“Indeed there is a Surah in the Qur’an of thirty Ayat, which intercedes for a man until he is forgiven. It is [Surah] Tabarak Alladhi Biyadihil-Mulk.”': '«തീർച്ചയായും ഖുർആനിൽ മുപ്പത് ആയത്തുകളുള്ള ഒരു സൂറത്തുണ്ട്; പാപമോചനം ലഭിക്കുന്നതുവരെ അത് ഒരു മനുഷ്യനുവേണ്ടി ശുപാർശ ചെയ്യുന്നു. അതാണ് തബാറകല്ലദീ ബിയദിഹിൽ മുൽക്ക്.»',
